          "java": "// Truth tables for implication and its variants, plus a direct proof check\npublic class PropositionalLogic {\n    static boolean implies(boolean p, boolean q) {\n        return !p || q; // false only when p is true and q is false\n    }\n\n    static boolean biconditional(boolean p, boolean q) {\n        return p == q;\n    }\n\n    static String tf(boolean b) {\n        return b ? \"T\" : \"F\";\n    }\n\n    static String yesNo(boolean b) {\n        return b ? \"yes\" : \"no\";\n    }\n\n    public static void main(String[] args) {\n        boolean[] values = {false, true};\n        boolean sameAsOr = true, sameAsContra = true, sameAsConverse = true;\n        System.out.println(\"p q | p->q  ~p|q  ~q->~p  q->p  p<->q\");\n        for (boolean p : values) {\n            for (boolean q : values) {\n                boolean imp = implies(p, q);\n                boolean orForm = !p || q;\n                boolean contra = implies(!q, !p);\n                boolean converse = implies(q, p);\n                // Two formulas are equivalent only if they agree on EVERY row\n                sameAsOr &= imp == orForm;\n                sameAsContra &= imp == contra;\n                sameAsConverse &= imp == converse;\n                System.out.println(tf(p) + \" \" + tf(q) + \" |  \" + tf(imp) + \"     \" + tf(orForm) + \"      \"\n                        + tf(contra) + \"      \" + tf(converse) + \"     \" + tf(biconditional(p, q)));\n            }\n        }\n        System.out.println(\"p->q equivalent to ~p|q?            \" + yesNo(sameAsOr));\n        System.out.println(\"p->q equivalent to ~q->~p?          \" + yesNo(sameAsContra));\n        System.out.println(\"p->q equivalent to converse q->p?   \" + yesNo(sameAsConverse));\n\n        // Claim: if n is odd, then n^2 is odd. Test it on many cases first...\n        int tested = 0, oddSquares = 0;\n        for (int n = 1; n < 100; n += 2) {\n            tested++;\n            if ((n * n) % 2 == 1) oddSquares++;\n        }\n        System.out.println(\"odd n in 1..99 with odd n^2: \" + oddSquares + \" of \" + tested);\n        // ...but only an argument that works for every n is a proof\n        System.out.println(\"Direct proof: assume n = 2k+1, then n^2 = 2(2k^2+2k)+1, which is odd.\");\n    }\n}\n",
          "cpp": "// Truth tables for implication and its variants, plus a direct proof check\n#include <iostream>\n#include <string>\n\nbool implies(bool p, bool q) {\n    return !p || q;  // false only when p is true and q is false\n}\n\nbool biconditional(bool p, bool q) { return p == q; }\n\nstd::string tf(bool b) { return b ? \"T\" : \"F\"; }\n\nstd::string yesNo(bool b) { return b ? \"yes\" : \"no\"; }\n\nint main() {\n    const bool values[] = {false, true};\n    bool sameAsOr = true, sameAsContra = true, sameAsConverse = true;\n    std::cout << \"p q | p->q  ~p|q  ~q->~p  q->p  p<->q\\n\";\n    for (bool p : values) {\n        for (bool q : values) {\n            bool imp = implies(p, q);\n            bool orForm = !p || q;\n            bool contra = implies(!q, !p);\n            bool converse = implies(q, p);\n            // Two formulas are equivalent only if they agree on EVERY row\n            sameAsOr = sameAsOr && imp == orForm;\n            sameAsContra = sameAsContra && imp == contra;\n            sameAsConverse = sameAsConverse && imp == converse;\n            std::cout << tf(p) << \" \" << tf(q) << \" |  \" << tf(imp) << \"     \" << tf(orForm) << \"      \"\n                      << tf(contra) << \"      \" << tf(converse) << \"     \" << tf(biconditional(p, q)) << \"\\n\";\n        }\n    }\n    std::cout << \"p->q equivalent to ~p|q?            \" << yesNo(sameAsOr) << \"\\n\";\n    std::cout << \"p->q equivalent to ~q->~p?          \" << yesNo(sameAsContra) << \"\\n\";\n    std::cout << \"p->q equivalent to converse q->p?   \" << yesNo(sameAsConverse) << \"\\n\";\n\n    // Claim: if n is odd, then n^2 is odd. Test it on many cases first...\n    int tested = 0, oddSquares = 0;\n    for (int n = 1; n < 100; n += 2) {\n        tested++;\n        if ((n * n) % 2 == 1) oddSquares++;\n    }\n    std::cout << \"odd n in 1..99 with odd n^2: \" << oddSquares << \" of \" << tested << \"\\n\";\n    // ...but only an argument that works for every n is a proof\n    std::cout << \"Direct proof: assume n = 2k+1, then n^2 = 2(2k^2+2k)+1, which is odd.\\n\";\n}\n",
          "python": "# Truth tables for implication and its variants, plus a direct proof check\n\n\ndef implies(p: bool, q: bool) -> bool:\n    return (not p) or q  # false only when p is true and q is false\n\n\ndef biconditional(p: bool, q: bool) -> bool:\n    return p == q\n\n\ndef tf(b: bool) -> str:\n    return \"T\" if b else \"F\"\n\n\ndef yes_no(b: bool) -> str:\n    return \"yes\" if b else \"no\"\n\n\nsame_as_or = same_as_contra = same_as_converse = True\nprint(\"p q | p->q  ~p|q  ~q->~p  q->p  p<->q\")\nfor p in (False, True):\n    for q in (False, True):\n        imp = implies(p, q)\n        or_form = (not p) or q\n        contra = implies(not q, not p)\n        converse = implies(q, p)\n        # Two formulas are equivalent only if they agree on EVERY row\n        same_as_or &= imp == or_form\n        same_as_contra &= imp == contra\n        same_as_converse &= imp == converse\n        print(f\"{tf(p)} {tf(q)} |  {tf(imp)}     {tf(or_form)}      \"\n              f\"{tf(contra)}      {tf(converse)}     {tf(biconditional(p, q))}\")\nprint(\"p->q equivalent to ~p|q?            \" + yes_no(same_as_or))\nprint(\"p->q equivalent to ~q->~p?          \" + yes_no(same_as_contra))\nprint(\"p->q equivalent to converse q->p?   \" + yes_no(same_as_converse))\n\n# Claim: if n is odd, then n^2 is odd. Test it on many cases first...\nodds = range(1, 100, 2)\nodd_squares = sum(1 for n in odds if (n * n) % 2 == 1)\nprint(f\"odd n in 1..99 with odd n^2: {odd_squares} of {len(odds)}\")\n# ...but only an argument that works for every n is a proof\nprint(\"Direct proof: assume n = 2k+1, then n^2 = 2(2k^2+2k)+1, which is odd.\")\n",
          "javascript": "// Truth tables for implication and its variants, plus a direct proof check\nconst implies = (p, q) => !p || q; // false only when p is true and q is false\nconst biconditional = (p, q) => p === q;\nconst tf = (b) => (b ? 'T' : 'F');\nconst yesNo = (b) => (b ? 'yes' : 'no');\n\nlet sameAsOr = true;\nlet sameAsContra = true;\nlet sameAsConverse = true;\nconsole.log('p q | p->q  ~p|q  ~q->~p  q->p  p<->q');\nfor (const p of [false, true]) {\n  for (const q of [false, true]) {\n    const imp = implies(p, q);\n    const orForm = !p || q;\n    const contra = implies(!q, !p);\n    const converse = implies(q, p);\n    // Two formulas are equivalent only if they agree on EVERY row\n    sameAsOr = sameAsOr && imp === orForm;\n    sameAsContra = sameAsContra && imp === contra;\n    sameAsConverse = sameAsConverse && imp === converse;\n    console.log(`${tf(p)} ${tf(q)} |  ${tf(imp)}     ${tf(orForm)}      ` +\n      `${tf(contra)}      ${tf(converse)}     ${tf(biconditional(p, q))}`);\n  }\n}\nconsole.log('p->q equivalent to ~p|q?            ' + yesNo(sameAsOr));\nconsole.log('p->q equivalent to ~q->~p?          ' + yesNo(sameAsContra));\nconsole.log('p->q equivalent to converse q->p?   ' + yesNo(sameAsConverse));\n\n// Claim: if n is odd, then n^2 is odd. Test it on many cases first...\nlet tested = 0;\nlet oddSquares = 0;\nfor (let n = 1; n < 100; n += 2) {\n  tested++;\n  if ((n * n) % 2 === 1) oddSquares++;\n}\nconsole.log(`odd n in 1..99 with odd n^2: ${oddSquares} of ${tested}`);\n// ...but only an argument that works for every n is a proof\nconsole.log('Direct proof: assume n = 2k+1, then n^2 = 2(2k^2+2k)+1, which is odd.');\n"
