          "code": {
            "java": "import java.util.ArrayList;\nimport java.util.List;\n\n// An implication versus its converse, inverse and contrapositive\npublic class ImplicationVariants {\n    static boolean implies(boolean p, boolean q) {\n        return !p || q;\n    }\n\n    static String tf(boolean b) {\n        return b ? \"T\" : \"F\";\n    }\n\n    public static void main(String[] args) {\n        boolean[] values = {false, true};\n        boolean contraMatches = true, converseMatches = true, inverseMatchesConverse = true;\n        System.out.println(\"p q | p->q  q->p  ~p->~q  ~q->~p\");\n        for (boolean p : values) {\n            for (boolean q : values) {\n                boolean imp = implies(p, q);\n                boolean converse = implies(q, p);\n                boolean inverse = implies(!p, !q);\n                boolean contra = implies(!q, !p);\n                contraMatches &= imp == contra;\n                converseMatches &= imp == converse;\n                inverseMatchesConverse &= inverse == converse;\n                String note = imp ? \"\" : \"   <- the only row where p->q is false\";\n                System.out.println(tf(p) + \" \" + tf(q) + \" |  \" + tf(imp) + \"     \" + tf(converse) + \"      \"\n                        + tf(inverse) + \"       \" + tf(contra) + note);\n            }\n        }\n        System.out.println(\"contrapositive matches p->q on every row: \" + contraMatches);\n        System.out.println(\"converse matches p->q on every row:       \" + converseMatches);\n        System.out.println(\"inverse matches converse on every row:    \" + inverseMatchesConverse);\n\n        // p: \"4 divides n\", q: \"n is even\". The implication holds; its converse does not.\n        List<Integer> implicationFails = new ArrayList<>();\n        List<Integer> converseFails = new ArrayList<>();\n        for (int n = 1; n <= 12; n++) {\n            boolean p = n % 4 == 0, q = n % 2 == 0;\n            if (!implies(p, q)) implicationFails.add(n);\n            if (!implies(q, p)) converseFails.add(n);\n        }\n        System.out.println(\"n in 1..12 breaking \\\"4 | n -> n even\\\": \" + implicationFails);\n        System.out.println(\"n in 1..12 breaking \\\"n even -> 4 | n\\\": \" + converseFails);\n    }\n}\n",
            "cpp": "// An implication versus its converse, inverse and contrapositive\n#include <iostream>\n#include <string>\n#include <vector>\n\nbool implies(bool p, bool q) { return !p || q; }\n\nstd::string tf(bool b) { return b ? \"T\" : \"F\"; }\n\nstd::string boolText(bool b) { return b ? \"true\" : \"false\"; }\n\nstd::string listText(const std::vector<int>& v) {\n    std::string s = \"[\";\n    for (size_t i = 0; i < v.size(); i++) s += (i ? \", \" : \"\") + std::to_string(v[i]);\n    return s + \"]\";\n}\n\nint main() {\n    const bool values[] = {false, true};\n    bool contraMatches = true, converseMatches = true, inverseMatchesConverse = true;\n    std::cout << \"p q | p->q  q->p  ~p->~q  ~q->~p\\n\";\n    for (bool p : values) {\n        for (bool q : values) {\n            bool imp = implies(p, q);\n            bool converse = implies(q, p);\n            bool inverse = implies(!p, !q);\n            bool contra = implies(!q, !p);\n            contraMatches = contraMatches && imp == contra;\n            converseMatches = converseMatches && imp == converse;\n            inverseMatchesConverse = inverseMatchesConverse && inverse == converse;\n            std::string note = imp ? \"\" : \"   <- the only row where p->q is false\";\n            std::cout << tf(p) << \" \" << tf(q) << \" |  \" << tf(imp) << \"     \" << tf(converse) << \"      \"\n                      << tf(inverse) << \"       \" << tf(contra) << note << \"\\n\";\n        }\n    }\n    std::cout << \"contrapositive matches p->q on every row: \" << boolText(contraMatches) << \"\\n\";\n    std::cout << \"converse matches p->q on every row:       \" << boolText(converseMatches) << \"\\n\";\n    std::cout << \"inverse matches converse on every row:    \" << boolText(inverseMatchesConverse) << \"\\n\";\n\n    // p: \"4 divides n\", q: \"n is even\". The implication holds; its converse does not.\n    std::vector<int> implicationFails, converseFails;\n    for (int n = 1; n <= 12; n++) {\n        bool p = n % 4 == 0, q = n % 2 == 0;\n        if (!implies(p, q)) implicationFails.push_back(n);\n        if (!implies(q, p)) converseFails.push_back(n);\n    }\n    std::cout << \"n in 1..12 breaking \\\"4 | n -> n even\\\": \" << listText(implicationFails) << \"\\n\";\n    std::cout << \"n in 1..12 breaking \\\"n even -> 4 | n\\\": \" << listText(converseFails) << \"\\n\";\n}\n",
            "python": "# An implication versus its converse, inverse and contrapositive\n\n\ndef implies(p: bool, q: bool) -> bool:\n    return (not p) or q\n\n\ndef tf(b: bool) -> str:\n    return \"T\" if b else \"F\"\n\n\ncontra_matches = converse_matches = inverse_matches_converse = True\nprint(\"p q | p->q  q->p  ~p->~q  ~q->~p\")\nfor p in (False, True):\n    for q in (False, True):\n        imp = implies(p, q)\n        converse = implies(q, p)\n        inverse = implies(not p, not q)\n        contra = implies(not q, not p)\n        contra_matches &= imp == contra\n        converse_matches &= imp == converse\n        inverse_matches_converse &= inverse == converse\n        note = \"\" if imp else \"   <- the only row where p->q is false\"\n        print(f\"{tf(p)} {tf(q)} |  {tf(imp)}     {tf(converse)}      {tf(inverse)}       {tf(contra)}{note}\")\nprint(f\"contrapositive matches p->q on every row: {str(contra_matches).lower()}\")\nprint(f\"converse matches p->q on every row:       {str(converse_matches).lower()}\")\nprint(f\"inverse matches converse on every row:    {str(inverse_matches_converse).lower()}\")\n\n# p: \"4 divides n\", q: \"n is even\". The implication holds; its converse does not.\nimplication_fails = [n for n in range(1, 13) if not implies(n % 4 == 0, n % 2 == 0)]\nconverse_fails = [n for n in range(1, 13) if not implies(n % 2 == 0, n % 4 == 0)]\nprint(f'n in 1..12 breaking \"4 | n -> n even\": {implication_fails}')\nprint(f'n in 1..12 breaking \"n even -> 4 | n\": {converse_fails}')\n",
            "javascript": "// An implication versus its converse, inverse and contrapositive\nconst implies = (p, q) => !p || q;\nconst tf = (b) => (b ? 'T' : 'F');\n\nlet contraMatches = true;\nlet converseMatches = true;\nlet inverseMatchesConverse = true;\nconsole.log('p q | p->q  q->p  ~p->~q  ~q->~p');\nfor (const p of [false, true]) {\n  for (const q of [false, true]) {\n    const imp = implies(p, q);\n    const converse = implies(q, p);\n    const inverse = implies(!p, !q);\n    const contra = implies(!q, !p);\n    contraMatches = contraMatches && imp === contra;\n    converseMatches = converseMatches && imp === converse;\n    inverseMatchesConverse = inverseMatchesConverse && inverse === converse;\n    const note = imp ? '' : '   <- the only row where p->q is false';\n    console.log(`${tf(p)} ${tf(q)} |  ${tf(imp)}     ${tf(converse)}      ${tf(inverse)}       ${tf(contra)}${note}`);\n  }\n}\nconsole.log(`contrapositive matches p->q on every row: ${contraMatches}`);\nconsole.log(`converse matches p->q on every row:       ${converseMatches}`);\nconsole.log(`inverse matches converse on every row:    ${inverseMatchesConverse}`);\n\n// p: \"4 divides n\", q: \"n is even\". The implication holds; its converse does not.\nconst ns = Array.from({ length: 12 }, (_, i) => i + 1);\nconst implicationFails = ns.filter((n) => !implies(n % 4 === 0, n % 2 === 0));\nconst converseFails = ns.filter((n) => !implies(n % 2 === 0, n % 4 === 0));\nconsole.log(`n in 1..12 breaking \"4 | n -> n even\": [${implicationFails.join(', ')}]`);\nconsole.log(`n in 1..12 breaking \"n even -> 4 | n\": [${converseFails.join(', ')}]`);\n"
          },
