            "java": "same parity: {(1,1), (1,3), (2,2), (2,4), (3,1), (3,3), (4,2), (4,4)}\n  reflexive=yes symmetric=yes antisymmetric=no transitive=yes -> equivalence relation\n  classes: {1, 3} {2, 4}\ndivides: {(1,1), (1,2), (1,3), (1,4), (2,2), (2,4), (3,3), (4,4)}\n  reflexive=yes symmetric=no antisymmetric=yes transitive=yes -> partial order\nless than: {(1,2), (1,3), (1,4), (2,3), (2,4), (3,4)}\n  reflexive=no symmetric=no antisymmetric=yes transitive=yes -> neither\nR: {(1,2), (2,1)}\n  reflexive=no symmetric=yes antisymmetric=no transitive=no -> neither\n  not transitive: (1,2) and (2,1) are in R but (1,1) is not",
            "python": "same parity: {(1,1), (1,3), (2,2), (2,4), (3,1), (3,3), (4,2), (4,4)}\n  reflexive=yes symmetric=yes antisymmetric=no transitive=yes -> equivalence relation\n  classes: {1, 3} {2, 4}\ndivides: {(1,1), (1,2), (1,3), (1,4), (2,2), (2,4), (3,3), (4,4)}\n  reflexive=yes symmetric=no antisymmetric=yes transitive=yes -> partial order\nless than: {(1,2), (1,3), (1,4), (2,3), (2,4), (3,4)}\n  reflexive=no symmetric=no antisymmetric=yes transitive=yes -> neither\nR: {(1,2), (2,1)}\n  reflexive=no symmetric=yes antisymmetric=no transitive=no -> neither\n  not transitive: (1,2) and (2,1) are in R but (1,1) is not",
            "javascript": "same parity: {(1,1), (1,3), (2,2), (2,4), (3,1), (3,3), (4,2), (4,4)}\n  reflexive=yes symmetric=yes antisymmetric=no transitive=yes -> equivalence relation\n  classes: {1, 3} {2, 4}\ndivides: {(1,1), (1,2), (1,3), (1,4), (2,2), (2,4), (3,3), (4,4)}\n  reflexive=yes symmetric=no antisymmetric=yes transitive=yes -> partial order\nless than: {(1,2), (1,3), (1,4), (2,3), (2,4), (3,4)}\n  reflexive=no symmetric=no antisymmetric=yes transitive=yes -> neither\nR: {(1,2), (2,1)}\n  reflexive=no symmetric=yes antisymmetric=no transitive=no -> neither\n  not transitive: (1,2) and (2,1) are in R but (1,1) is not",
            "cpp": "same parity: {(1,1), (1,3), (2,2), (2,4), (3,1), (3,3), (4,2), (4,4)}\n  reflexive=yes symmetric=yes antisymmetric=no transitive=yes -> equivalence relation\n  classes: {1, 3} {2, 4}\ndivides: {(1,1), (1,2), (1,3), (1,4), (2,2), (2,4), (3,3), (4,4)}\n  reflexive=yes symmetric=no antisymmetric=yes transitive=yes -> partial order\nless than: {(1,2), (1,3), (1,4), (2,3), (2,4), (3,4)}\n  reflexive=no symmetric=no antisymmetric=yes transitive=yes -> neither\nR: {(1,2), (2,1)}\n  reflexive=no symmetric=yes antisymmetric=no transitive=no -> neither\n  not transitive: (1,2) and (2,1) are in R but (1,1) is not"
